var hex = msg.payload
let r = parseInt(hex.substr(1, 2), 16) / 255;
let g = parseInt(hex.substr(3, 2), 16) / 255;
let b = parseInt(hex.substr(5, 2), 16) / 255;

const lin = c =>
  c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);

r = lin(r);
g = lin(g);
b = lin(b);

const X = r * 0.4124 + g * 0.3576 + b * 0.1805;
const Y = r * 0.2126 + g * 0.7152 + b * 0.0722;
const Z = r * 0.0193 + g * 0.1192 + b * 0.9505;

const sum = X + Y + Z;
msg.payload = {}
msg.payload.color = { x: X / sum, y: Y / sum };
return msg;

function xyToHex({ x, y }, Y = 1) {
  if (y === 0) return "#000000";

  // xyY → XYZ
  const X = (x * Y) / y;
  const Z = ((1 - x - y) * Y) / y;

  // XYZ → linear RGB (sRGB, D65)
  let r =  3.2406 * X - 1.5372 * Y - 0.4986 * Z;
  let g = -0.9689 * X + 1.8758 * Y + 0.0415 * Z;
  let b =  0.0557 * X - 0.2040 * Y + 1.0570 * Z;

  // Clamp negatives
  r = Math.max(0, r);
  g = Math.max(0, g);
  b = Math.max(0, b);

  // Linear → sRGB
  const gamma = c =>
    c <= 0.0031308
      ? 12.92 * c
      : 1.055 * Math.pow(c, 1 / 2.4) - 0.055;

  r = gamma(r);
  g = gamma(g);
  b = gamma(b);

  // Normalize if needed
  const max = Math.max(r, g, b);
  if (max > 1) {
    r /= max;
    g /= max;
    b /= max;
  }

  // To #RRGGBB
  const toHex = c =>
    Math.round(c * 255)
      .toString(16)
      .padStart(2, "0");

  //return `${x}-${y}`;
  return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}
var xycolor = msg.payload.color;
msg.payload = xyToHex(xycolor);
return msg;
